/**
 * Generates src/styles/_tokens.generated.scss from src/theme/tokens.ts.
 * Run with: node scripts/build-tokens.ts  (Node 22.6+ strips TS types natively)
 */
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import {
  palette,
  semantic,
  font,
  fontSize,
  fontWeight,
  radius,
  space,
  shadow,
  controlHeight,
} from '../src/theme/tokens.ts';

const out = fileURLToPath(new URL('../src/styles/_tokens.generated.scss', import.meta.url));

const lines: string[] = [
  '// AUTO-GENERATED by scripts/build-tokens.ts from src/theme/tokens.ts — do not edit.',
  ':root {',
  '  // Palette',
  ...Object.entries(palette).map(([k, v]) => `  --${k}: ${v};`),
  '',
  '  // Semantic',
  ...Object.entries(semantic).map(([k, v]) => `  --${k}: var(--${v});`),
  '',
  '  // Type',
  `  --font-family: ${font.family};`,
  `  --font-mono: ${font.mono};`,
  ...Object.entries(fontSize).map(([k, v]) => `  --fs-${k}: ${v};`),
  ...Object.entries(fontWeight).map(([k, v]) => `  --fw-${k}: ${v};`),
  '',
  '  // Shape & space',
  ...Object.entries(radius).map(([k, v]) => `  --radius-${k}: ${v};`),
  ...Object.entries(space).map(([k, v]) => `  --space-${k}: ${v};`),
  ...Object.entries(shadow).map(([k, v]) => `  --shadow-${k}: ${v};`),
  ...Object.entries(controlHeight).map(([k, v]) => `  --control-${k}: ${v}px;`),
  '}',
  '',
];

writeFileSync(out, lines.join('\n'));
console.log(`tokens → ${out}`);
